//go:build bdd

// Code generated by `true-bdd build tests`. DO NOT EDIT.
//
// Source: docs/scenarios.yaml
//
// One Go test per registry scenario, with the scenario's steps stated
// literally: what a reader sees here is what the machine runs. Done
// checks these steps against the registry before running any of them,
// so a hand edit to either side fails the test rather than quietly
// making the two documents disagree.
//
// Scenarios sharing a `path:` are written here in id order, so an
// inserted scenario lands where a reader expects it instead of at the
// end. Sequential by design — the suite's harness is shared.

package calc_test

import (
	"testing"

	"fixture/stepsrun/tests/calc/scenarios"
)

// calc-001-double: Double a number
func TestCalc001Double(t *testing.T) {
	s := scenarios.New(t, "calc-001-double")
	s.Given(`the number is 2`)
	s.When(`the number is doubled`)
	s.Then(`the result is 4`)
	s.Done()
}

// calc-002-shared: Observe an unchanged number through the shared definition
func TestCalc002Shared(t *testing.T) {
	s := scenarios.New(t, "calc-002-shared")
	s.Given(`the number is 3`)
	s.Then(`the result is 3`)
	s.Done()
}

package steps

import ("fmt"; "strconv")

func Register(suite Registrar) {
 suite.Step(`^the number is (\d+)$`, number)
 suite.Step(`^the number is doubled$`, doubled)
 suite.Step(`^the result is (\d+)$`, result)
}

// number prepares the state: it stores the captured number and nothing else.
func number(state *State, args []string) error {
 value, err := strconv.Atoi(args[0])
 if err != nil {
  return fmt.Errorf("the number is %q: expected an integer, got an unparsable value: %w", args[0], err)
 }
 state.Value = value
 return nil
}

// doubled acts on the state: it multiplies the current number by two.
func doubled(state *State, _ []string) error {
 state.Value *= 2
 return nil
}
func result(state *State, args []string) error {
 want, err := strconv.Atoi(args[0]); if err != nil { return err }
 if state.Value != want { return fmt.Errorf("expected %d, got %d", want, state.Value) }; return nil
}
